SELECT 
FROM tb_reservation r
LEFT JOIN tb_reservation_batch b ON r.batch_id = b.id
LEFT JOIN tb_equipment e ON b.equipment_id = e.id
LEFT JOIN tb_laboratory l ON e.laboratory_id = l.id


        AND r.batch_id = #{q.batchId}


        AND r.status = #{q.status}


        AND r.user_id = #{userId}


        AND l.admin_user_id = #{adminUserId}


ORDER BY r.id DESC
